from math import comb
from typing import List

def rob_houses(n: int, y: int, x: int, a: List[int]) -> int:
    # p[i] 是第 i 个房子（0-based）在直线上的坐标
    p = [0] * n
    for i in range(1, n):
        p[i] = p[i - 1] + a[i - 1]
    if y == 1:
        return n  # 只抢一家，路程为 0，是任何 x 的倍数
    ways = 0
    for i in range(n):
        for j in range(i + y - 1, n):
            if (p[j] - p[i]) % x == 0:
                # 中间 j-i-1 个房子里再挑 y-2 个，正反两个方向
                ways += 2 * comb(j - i - 1, y - 2)
    return ways
